using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;
using RichAudio.Beacon.Transport;using RichAudio.Integration;using RichAudio.Integration.Shvdne;using GTA.Native;
class TestShvdneTrace02B {
 static int checks;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=1048576};static long F=Stopwatch.Frequency;
 static void Check(bool v,string why){if(!v)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
 static Dictionary<string,object> Map(object v){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(v));}
 static ObservationRecord02B[] Take(StartupTrace02B t){var map=Map(t.Drain());var raw=((System.Collections.IEnumerable)map["records"]).Cast<object>().ToArray();return raw.Select(x=>Json.Deserialize<ObservationRecord02B>(Json.Serialize(x))).ToArray();}
 sealed class Source:IGameObservationSource {
  public long Clock=Stopwatch.Frequency*10,ReadyCost,InteriorCost;public bool Ready=true,Driver=true,Alive=true;public uint Model=0xf9300cc5;public bool Collect;
  public bool StoryReady{get{Clock+=ReadyCost;if(Collect)GC.Collect(0);return Ready;}}public int PlayerVehicleHandle{get{return Driver?257:0;}}
  public CameraObservation ReadCamera(){return new CameraObservation{Before=Clock,After=Clock,Observed=Clock,GameTime=(uint)(Clock*1000/F),Position=new[]{0d,0d,1d},Forward=new[]{0d,1d,0d},Up=new[]{0d,0d,1d}};}
  public GameplayInterior ReadCameraInterior(ListenerState l,out CameraInteriorReadback raw){Clock+=InteriorCost;raw=new CameraInteriorReadback{Outcome="no-proxy",Proxy=0,SampleTicks=Clock};return null;}
  public int[] DiscoverVehicles(double[] p,float radius){return new[]{257,513};}
  public VehicleObservation ReadVehicle(int h){return new VehicleObservation{Handle=h,Model=Model,Exists=Alive,PlayerDriver=Driver&&h==257,VehicleView=Driver&&h==257,Running=true,Before=Clock,After=Clock,Observed=Clock,Position=new[]{(double)(h==257?1:2),0d,0d},Velocity=new[]{0d,0d,0d},Forward=new[]{0d,1d,0d},Up=new[]{0d,0d,1d},OperatingPointEvidence="unavailable"};}
  public SharedFrameSampler Sampler(StartupTrace02B trace=null){var s=new SharedFrameSampler(new string('a',32),this,(m,c)=>true,4,()=>Clock);s.IncludeTransportObservations=true;s.StartupTrace=trace;return s;}
  public void Next(){Clock+=F/20;}
 }
 static string Wire(GameplayFrame f){return f==null?"null":Convert.ToBase64String(GameplayWire.Encode(f,f.Session));}
 static void Deterministic(){
  var a=new Source();var b=new Source();var trace=new StartupTrace02B(()=>a.Clock,()=>-1,()=>123);var current=a.Sampler(trace);var original=new BaselineSharedFrameSampler(new string('a',32),b,(m,c)=>true,4,()=>b.Clock);original.IncludeTransportObservations=true;
  for(int i=0;i<48;i++){if(i==5){a.Driver=b.Driver=false;}if(i==8){a.Alive=b.Alive=false;}if(i==9){a.Alive=b.Alive=true;a.Driver=b.Driver=true;}if(i==12){a.Model=b.Model=123;}if(i==15){a.Ready=b.Ready=false;}if(i==16){a.Ready=b.Ready=true;}if(i==20){a.ReadyCost=b.ReadyCost=F*17/1000;}if(i==21){a.ReadyCost=b.ReadyCost=0;}if(i==40){a.ReadyCost=b.ReadyCost=F*17/1000;}if(i==41){a.ReadyCost=b.ReadyCost=0;}
   Check(Wire(current.Capture())==Wire(original.Capture()),"exact archived/current frame and lifetime semantics "+i);a.Next();b.Next();}
  var all=new List<ObservationRecord02B>();while(true){var rows=Take(trace);if(rows.Length==0)break;all.AddRange(rows);}
  Check(all.Count==33&&all[32].Ordinal==41,"first 32 plus later-filter policy retains original anomalous ordinal without reordering");
  foreach(var r in all)Check(r.WallTicks.Sum()==r.EndQpc-r.BeginQpc&&r.ReconciliationTicks==0,"raw QPC reconciliation "+r.Ordinal);
  Check(all[20].WallTicks[(int)ObservationStage02B.Readiness]==F*17/1000,"authored readiness delay isolated to readiness");
  var s=new Source{InteriorCost=F*17/1000};var t=new StartupTrace02B(()=>s.Clock,()=>-1,()=>123);s.Sampler(t).Capture();var interior=Take(t)[0];Check(interior.WallTicks[(int)ObservationStage02B.Interior]==F*17/1000&&interior.WallTicks[(int)ObservationStage02B.Readiness]==0,"same residual magnitude now distinguishes interior from readiness");
  var convert=new Source();var ct=new StartupTrace02B(()=>convert.Clock,()=>-1,()=>123);var cs=new SharedFrameSampler(new string('a',32),convert,(m,c)=>{convert.Clock+=F*12/1000;return true;},4,()=>convert.Clock);cs.IncludeTransportObservations=true;cs.StartupTrace=ct;cs.Capture();Check(Take(ct)[0].WallTicks[(int)ObservationStage02B.SourceBookkeeping]>=F*12/1000,"authored source conversion/identity delay isolated");
  var notReady=new Source{Ready=false};var nt=new StartupTrace02B(()=>notReady.Clock,()=>-1,()=>123);Check(notReady.Sampler(nt).Capture()==null&&!Take(nt)[0].FrameReturned,"not-ready early return captured without fabricated frame");
  var gcSource=new Source{Collect=true};var gt=new StartupTrace02B(()=>gcSource.Clock,()=>-1,()=>123);gcSource.Sampler(gt).Capture();var gr=Take(gt)[0];Check(gr.GcAfter[0]>gr.GcBefore[0],"GC count correlation retained with process-wide scope");
  var many=new Source{InteriorCost=F*17/1000};var mt=new StartupTrace02B(()=>many.Clock,()=>-1,()=>123);var ms=many.Sampler(mt);for(int i=0;i<200;i++){ms.Capture();many.Next();}var summary=Map(mt.Drain());Check(Convert.ToInt32(summary["published"])==96&&Convert.ToInt32(summary["dropped"])==104,"record count and overflow bounded at 96 for lifetime");Check(((System.Collections.IEnumerable)summary["records"]).Cast<object>().Count()<=8,"worker drain bounded at eight records per packet");
  var faultSource=new Source();int reads=0;var ft=new StartupTrace02B(()=>{if(++reads==2)throw new InvalidOperationException("authored trace clock failure");return faultSource.Clock;},()=>-1,()=>123);Check(faultSource.Sampler(ft).Capture()!=null&&Convert.ToBoolean(Map(ft.Drain())["disabled"]),"diagnostic clock failure isolates from normal observation semantics");
  int cpuCalls=0;var cpuSource=new Source();var failureCpu=new StartupTrace02B(()=>cpuSource.Clock,()=>{if(++cpuCalls>1)throw new InvalidOperationException("authored CPU failure");return 0;},()=>123);Check(cpuSource.Sampler(failureCpu).Capture()!=null&&Convert.ToInt64(Map(failureCpu.Drain())["diagnosticFaults"])==1,"CPU failure recorded once without stopping telemetry");
  var config=new ShvdneConfiguration{StartupTiming02B=true,TransportValidationOnly=true,HostEnabled=true,MenuEnabled=false};config.Validate();config.AllowMemoryTelemetry=true;bool rejected=false;try{config.Validate();}catch(InvalidDataException){rejected=true;}Check(rejected,"diagnostic configuration refuses optional mechanical telemetry");
  Check(Json.Serialize(summary).Length<32768,"bounded eight-record trace fits reserved journal payload budget");
  var raceSource=new Source{InteriorCost=F*17/1000};var raceTrace=new StartupTrace02B(()=>raceSource.Clock,()=>-1,()=>123);var raceSampler=raceSource.Sampler(raceTrace);var received=new List<ObservationRecord02B>();int done=0;Exception raceError=null;
  var worker=new Thread(()=>{try{for(int i=0;i<2000;i++){var chunk=Take(raceTrace);received.AddRange(chunk);if(Volatile.Read(ref done)!=0&&chunk.Length==0)break;}}catch(Exception e){raceError=e;}});worker.Start();for(int i=0;i<200;i++){raceSampler.Capture();raceSource.Next();}Volatile.Write(ref done,1);Check(worker.Join(3000)&&raceError==null,"concurrent diagnostic drain completes without producer locks");while(true){var more=Take(raceTrace);if(more.Length==0)break;received.AddRange(more);}Check(received.Count==96&&received.Select(r=>r.Ordinal).Distinct().Count()==96&&received.All(r=>r.ReconciliationTicks==0&&r.WallTicks.Sum()==r.EndQpc-r.BeginQpc),"concurrent slot publication exposes complete immutable records only");
 }
 static Func<Hash,object[],object> Respond(){return (Func<Hash,object[],object>)Delegate.CreateDelegate(typeof(Func<Hash,object[],object>),typeof(TestShvdneGameSource).GetMethod("Respond",BindingFlags.NonPublic|BindingFlags.Static));}
 static void NativeCamera(){
  var baseline=Respond();var hashes=new[]{Hash.GET_FINAL_RENDERED_CAM_COORD,Hash.GET_FINAL_RENDERED_CAM_ROT,Hash.GET_GAME_TIMER,Hash.IS_PAUSE_MENU_ACTIVE};var stages=new[]{ObservationStage02B.CameraCoordinate,ObservationStage02B.CameraRotation,ObservationStage02B.GameTime,ObservationStage02B.PauseState};
  for(int i=0;i<hashes.Length;i++){int index=i;Function.Calls.Clear();Function.Response=(h,args)=>{if(h==hashes[index])Thread.Sleep(15);return baseline(h,args);};var provider=new ShvdneGameSource();var trace=new StartupTrace02B(null,()=>-1,()=>123);provider.StartupTrace=trace;var sampler=new SharedFrameSampler(new string('a',32),provider,(m,c)=>true,4);sampler.IncludeTransportObservations=true;sampler.StartupTrace=trace;Check(sampler.Capture()==null&&sampler.LastStatus=="listener-acquisition-invalid","slow camera acquisition retains invalid listener semantics "+i);var record=Take(trace)[0];Check(record.WallTicks[(int)stages[i]]*1000d/F>=14&&record.CameraCallsReturned==15,"actual provider localizes authored slow native API call "+i);Check(record.CameraAfterQpc-record.CameraBeforeQpc>=F/100&&record.ReconciliationTicks==0,"native bracket and full timing survive rejected acquisition "+i);Check(Math.Abs(sampler.Timing.Batch.Maximum-(record.EndQpc-record.BeginQpc)*1000d/F)<1000d/F,"trace reconciles to existing full-batch endpoint "+i);}
  Function.Response=baseline;Function.Calls.Clear();var source=new ShvdneGameSource();var before=source.ReadCamera();var order=Function.Calls.Select(x=>x.Item1).ToArray();Function.Calls.Clear();var t=new StartupTrace02B(null,()=>-1,()=>123);source.StartupTrace=t;t.Begin(Stopwatch.GetTimestamp());var after=source.ReadCamera();t.Complete(Stopwatch.GetTimestamp(),"fixture-camera",false,null);Check(order.SequenceEqual(Function.Calls.Select(x=>x.Item1))&&before.Position.SequenceEqual(after.Position)&&before.Forward.SequenceEqual(after.Forward)&&before.Up.SequenceEqual(after.Up)&&before.GameTime==after.GameTime&&before.Paused==after.Paused,"actual provider preserves API order and exact camera values");
  Function.Calls.Clear();Function.Response=(h,args)=>{if(h==Hash.GET_FINAL_RENDERED_CAM_ROT)throw new InvalidOperationException("authored native fault");return baseline(h,args);};var throwing=new ShvdneGameSource();var tt=new StartupTrace02B(null,()=>-1,()=>123);throwing.StartupTrace=tt;tt.Begin(Stopwatch.GetTimestamp());bool caught=false;try{throwing.ReadCamera();}catch(InvalidOperationException){caught=true;}tt.Complete(Stopwatch.GetTimestamp(),"exception",false,"InvalidOperationException");var rr=Take(tt)[0];Check(caught&&rr.CameraCallsReturned==1&&rr.CameraAfterQpc==null&&!Function.Calls.Any(x=>x.Item1==Hash.GET_GAME_TIMER),"native exception order, incomplete bracket and original exception preserved");
 }
 static double Quantile(List<double> values,double p){var a=values.OrderBy(x=>x).ToArray();return a[(int)Math.Ceiling(a.Length*p)-1];}
 static void Overhead(string path){
  var standalone=new StartupTrace02B();long standaloneAt=Stopwatch.GetTimestamp();standalone.Begin(standaloneAt);for(int j=0;j<(int)ObservationStage02B.Count;j++)standalone.Mark((ObservationStage02B)j);standalone.Complete(Stopwatch.GetTimestamp(),"offline-cold-recorder",false,null);double standaloneColdMs=(Stopwatch.GetTimestamp()-standaloneAt)*1000d/F;
  var baselineSource=new Source();var newSource=new Source();var disabledSource=new Source();var baseline=new BaselineSharedFrameSampler(new string('a',32),baselineSource,(m,c)=>true,4,()=>baselineSource.Clock);baseline.IncludeTransportObservations=true;
  var tracer=new StartupTrace02B(()=>{Stopwatch.GetTimestamp();return newSource.Clock;});var enabled=newSource.Sampler(tracer);var disabled=disabledSource.Sampler();var added=new List<double>();var disabledAdded=new List<double>();var cold=new List<double>();var raw=new List<object>();
  for(int i=0;i<1024;i++){long at;double b,e,d;if(i%2==0){at=Stopwatch.GetTimestamp();baseline.Capture();b=(Stopwatch.GetTimestamp()-at)*1000d/F;at=Stopwatch.GetTimestamp();enabled.Capture();e=(Stopwatch.GetTimestamp()-at)*1000d/F;}else{at=Stopwatch.GetTimestamp();enabled.Capture();e=(Stopwatch.GetTimestamp()-at)*1000d/F;at=Stopwatch.GetTimestamp();baseline.Capture();b=(Stopwatch.GetTimestamp()-at)*1000d/F;}at=Stopwatch.GetTimestamp();disabled.Capture();d=(Stopwatch.GetTimestamp()-at)*1000d/F;double difference=e-b;raw.Add(new{ordinal=i+1,baselineMs=b,enabledMs=e,disabledMs=d,addedMs=difference});if(i<32)cold.Add(difference);else added.Add(difference);disabledAdded.Add(d-b);baselineSource.Next();newSource.Next();disabledSource.Next();}
  var cpu=new StartupTrace02B();cpu.Begin(Stopwatch.GetTimestamp());for(int i=0;i<25;i++){long until=Stopwatch.GetTimestamp()+F/500;while(Stopwatch.GetTimestamp()<until){}cpu.Mark(ObservationStage02B.Other);}cpu.Complete(Stopwatch.GetTimestamp(),"offline-cpu-calibration",false,null);var calibration=cpu.Drain();
  bool admit=Quantile(added,.5)<=.1&&Quantile(added,.95)<=.25&&Quantile(added,.99)<=.5&&cold.Max()<=2&&standaloneColdMs<=2;
  File.WriteAllText(path,Json.Serialize(new{passed=admit,scope="Paired authored full captures; alternating order, actual current-thread CPU interop and QPC read cost; all signed differences retained; cold standalone recorder measured separately; not live qualification",limits=new{medianAddedMs=.1,p95AddedMs=.25,p99AddedMs=.5,first32MaximumAddedMs=2,standaloneColdMaximumMs=2},standaloneColdMs,medianAddedMs=Quantile(added,.5),p95AddedMs=Quantile(added,.95),p99AddedMs=Quantile(added,.99),maximumAddedMs=added.Max(),first32MaximumAddedMs=cold.Max(),disabledP99AddedMs=Quantile(disabledAdded,.99),cpuCalibration=calibration,raw}));Check(admit,"predeclared offline instrumentation-overhead admission bounds");
 }
 static int Main(string[] args){try{if(args.Length>0&&args[0]=="overhead"){Overhead(args[1]);}else{Deterministic();NativeCamera();}Console.WriteLine("RESULT checks="+checks+" gameLaunched=false endpointOpened=false candidateExecuted=false");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
